<?php declare(strict_types=1);namespace App\Core;abstract class Controller{public function __construct(protected Config $config,protected Database $db){} protected function view(string $v,array $d=[]):void{View::render($v,$d);} protected function json(array $d,int $code=200):void{http_response_code($code);header('Content-Type: application/json');echo json_encode($d,JSON_THROW_ON_ERROR);} protected function redirect(string $to):void{header('Location: '.$to);exit;} protected function input(string $k,string $default=''):string{return trim((string)($_POST[$k]??$_GET[$k]??$default));}}
